/**
 * Chat domain types.
 * Represents the messages shown in the add-in conversation UI.
 */

import type { AgentMessageUsage } from "./session"

export type MessageRole = "user" | "assistant" | "tool"

interface BaseMessage {
  readonly id: string
  readonly timestamp: number
}

/** A file the user attached to their message (image or PDF, base64 data URL). */
export interface MessageAttachment {
  /** Original filename ("report.pdf"). */
  name: string
  /** MIME type ("image/png", "application/pdf"). */
  mime: string
  /** Base64 data URL — the wire payload and the local preview source. */
  dataUrl: string
  /** PDF sent as rendered page images (fallback for non-pdf models). */
  pageImages?: string[]
}

export interface UserMessage extends BaseMessage {
  readonly role: "user"
  readonly content: string
  attachments?: MessageAttachment[]
}

export interface AssistantMessage extends BaseMessage {
  readonly role: "assistant"
  /** Full content — grows as `assistant.delta` events arrive. */
  content: string
  /** Optional reasoning/thinking content from `msg.reasoning` (`reasoning_content`) or `_thinking` progress. */
  reasoning?: string
  /** `true` while the streaming turn is in flight; `false` once completed. */
  streaming?: boolean
  /** Persisted per-step metadata (model, tokens, cost, duration_ms). */
  usage?: AgentMessageUsage
  /** Images generated by the model (image-output models) — data URLs. */
  images?: string[]
}
export interface RunMeta {
  tokens: number
  durationMs: number
}


export interface ToolMessage extends BaseMessage {
  readonly role: "tool"
  readonly toolName: string
  /** Latest preview text from `tool.progress` / `tool.completed`. */
  preview?: string
  /** Flips to `true` on `tool.completed`. */
  completed: boolean
}

export type ChatMessage = UserMessage | AssistantMessage | ToolMessage
